def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    c_opp = 0
    c_me = 0
    for i in range(n):
        m, o = history[i]
        if o == 'C':
            c_opp += 1
        if m == 'C':
            c_me += 1

    d_opp = n - c_opp
    d_me = n - c_me
    last_m, last_o = history[n - 1]

    opp_streak_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_streak_d += 1
        i -= 1

    my_streak_d = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_streak_d += 1
        i -= 1

    recent_start = n - 8
    if recent_start < 0:
        recent_start = 0

    recent_d = 0
    for i in range(recent_start, n):
        if history[i][1] == 'D':
            recent_d += 1

    tolerated = 0
    punished = 0
    mirror_count = 0
    alt_count = 0

    for i in range(1, n):
        prev_m = history[i - 1][0]
        prev_o = history[i - 1][1]
        cur_m = history[i][0]
        cur_o = history[i][1]

        if prev_m == 'D':
            if cur_o == 'C':
                tolerated += 1
            else:
                punished += 1

        if cur_o == prev_m:
            mirror_count += 1

        if cur_o != prev_o:
            alt_count += 1

    if n > 1:
        denom = n - 1
        mirror_score = mirror_count / denom
        alt_score = alt_count / denom
    else:
        mirror_score = 0.0
        alt_score = 0.0

    coop_rate = c_opp / n

    if d_opp == 0:
        if tolerated > 0:
            return 'D'
        if d_me == 0:
            if n >= 65:
                return 'D'
            return 'C'
        if last_m == 'D':
            return 'C'
        return 'C'

    if c_opp == 0:
        return 'D'

    if opp_streak_d >= 3 or recent_d >= 4 or d_opp * 10 > n * 7:
        return 'D'

    if tolerated > 0:
        if last_o == 'C' and opp_streak_d == 0 and recent_d <= 2:
            return 'D'
        if last_o == 'D' and opp_streak_d == 1 and coop_rate > 0.5:
            return 'C'

    if last_m == 'D' and last_o == 'C' and tolerated == 0:
        if coop_rate > 0.5:
            return 'C'
        return 'D'

    if opp_streak_d >= 2:
        return 'D'

    if last_o == 'D':
        if coop_rate > 0.65:
            if n >= 4 and history[n - 3][1] == 'C' and history[n - 4][1] == 'C':
                return 'C'
            if recent_d <= 1:
                return 'C'

        if coop_rate > 0.5 and rng.random() < 0.25:
            return 'C'

        return 'D'

    if coop_rate >= 0.8 and mirror_score >= 0.7:
        return 'C'

    if n >= 6 and alt_score >= 0.8 and mirror_score < 0.7:
        return 'D'

    if mirror_score >= 0.7:
        return 'C'

    remaining = 100 - n
    if remaining <= 2:
        if coop_rate > 0.6 and opp_streak_d == 0 and punished == 0 and mirror_score < 0.75:
            return 'D'

    if (
        last_m == 'C'
        and last_o == 'C'
        and d_me == 0
        and coop_rate > 0.6
        and recent_d == 0
        and mirror_score < 0.7
        and n >= 75
    ):
        return 'D'

    if coop_rate > 0.6:
        return 'C'

    if recent_d >= 2:
        return 'D'

    if (
        coop_rate > 0.4
        and last_m == 'C'
        and last_o == 'C'
        and n >= 70
        and rng.random() < 0.05
    ):
        return 'D'

    return 'C'
